using Microsoft.Data.Sqlite;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Business.Services;

public sealed class SalesAndCashService(DatabaseInitializer db)
{
    public async Task<long?> GetOpenCashSessionAsync(CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id FROM CashSessions WHERE Status='OUVERTE' ORDER BY Id DESC LIMIT 1";var result=await cmd.ExecuteScalarAsync(ct);return result is null?null:Convert.ToInt64(result);}
    public async Task<long> OpenCashSessionAsync(long userId,long openingCashMinor,CancellationToken ct=default){if(openingCashMinor<0)throw new ArgumentOutOfRangeException(nameof(openingCashMinor));await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO CashSessions(UserId,OpenedAt,OpeningCashMinor,Status) SELECT $u,$d,$cash,'OUVERTE' WHERE NOT EXISTS(SELECT 1 FROM CashSessions WHERE Status='OUVERTE');SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$u",userId);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$cash",openingCashMinor);var id=await cmd.ExecuteScalarAsync(ct);if(id is null or DBNull)throw new InvalidOperationException("Une session de caisse est déjà ouverte.");return Convert.ToInt64(id);}
    public async Task<long> CheckoutAsync(SaleDraft sale,CancellationToken ct=default){if(sale.Lines.Count==0)throw new ArgumentException("Le panier est vide.");if(sale.Lines.Any(x=>x.Quantity<=0||x.UnitPriceMinor<0))throw new ArgumentException("Une ligne du panier est invalide.");if(sale.DiscountMinor<0)throw new ArgumentException("La remise ne peut pas être négative.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;if(!string.IsNullOrWhiteSpace(sale.IdempotencyKey)){cmd.CommandText="SELECT Id FROM Sales WHERE IdempotencyKey=$key";cmd.Parameters.AddWithValue("$key",sale.IdempotencyKey);var previous=await cmd.ExecuteScalarAsync(ct);if(previous is not null){await tx.CommitAsync(ct);return Convert.ToInt64(previous);}cmd.Parameters.Clear();}var role=await Role(c,(SqliteTransaction)tx,sale.UserId,ct);if(sale.DiscountMinor>0&&!IsManager(role))throw new UnauthorizedAccessException("Seul le responsable peut accorder une remise.");if(sale.CashSessionId is not null){cmd.CommandText="SELECT COUNT(*) FROM CashSessions WHERE Id=$s AND Status='OUVERTE'";cmd.Parameters.AddWithValue("$s",sale.CashSessionId.Value);if(Convert.ToInt64(await cmd.ExecuteScalarAsync(ct))!=1)throw new InvalidOperationException("La caisse n'est pas ouverte.");cmd.Parameters.Clear();}
            long total=0;foreach(var line in sale.Lines)total=checked(total+checked(line.UnitPriceMinor*line.Quantity));if(sale.DiscountMinor>total)throw new ArgumentException("La remise dépasse le total.");var due=total-sale.DiscountMinor;if(sale.Tenders.Count==0||sale.Tenders.Any(t=>t.AmountMinor<=0)||sale.Tenders.Sum(t=>t.AmountMinor)!=due)throw new ArgumentException("Le total des règlements doit correspondre exactement au montant dû.");if(sale.Tenders.Any(t=>(t.Method is "CARTE" or "MOBILE")&&string.IsNullOrWhiteSpace(t.Confirmation)))throw new ArgumentException("Confirmez manuellement chaque paiement par carte ou mobile.");
            var now=DateTimeOffset.Now;var number=$"V-{now:yyyyMMddHHmmss}-{Guid.NewGuid():N}"[..31];cmd.CommandText="INSERT INTO Sales(UserId,CashSessionId,ReceiptNumber,SoldAt,Status,TotalMinor,DiscountMinor,IdempotencyKey) VALUES($u,$session,$number,$date,'VALIDEE',$total,$discount,$key);SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$u",sale.UserId);cmd.Parameters.AddWithValue("$session",(object?)sale.CashSessionId??DBNull.Value);cmd.Parameters.AddWithValue("$number",number);cmd.Parameters.AddWithValue("$date",now.ToString("O"));cmd.Parameters.AddWithValue("$total",due);cmd.Parameters.AddWithValue("$discount",sale.DiscountMinor);cmd.Parameters.AddWithValue("$key",string.IsNullOrWhiteSpace(sale.IdempotencyKey)?DBNull.Value:sale.IdempotencyKey);var saleId=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));
            foreach(var line in sale.Lines){cmd.Parameters.Clear();cmd.CommandText="SELECT SalePriceMinor FROM Products WHERE Id=$p AND IsActive=1";cmd.Parameters.AddWithValue("$p",line.ProductId);var current=await cmd.ExecuteScalarAsync(ct);if(current is null)throw new InvalidOperationException($"Le produit {line.Name} n'est plus disponible.");if(Convert.ToInt64(current)!=line.UnitPriceMinor)throw new InvalidOperationException($"Le prix de {line.Name} a changé. Actualisez le panier.");cmd.Parameters.Clear();cmd.CommandText="INSERT INTO SaleLines(SaleId,ProductId,Quantity,UnitPriceMinor,LineTotalMinor,UnitCostMinor,ProductName) VALUES($s,$p,$q,$price,$lineTotal,0,$name);SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$s",saleId);cmd.Parameters.AddWithValue("$p",line.ProductId);cmd.Parameters.AddWithValue("$q",line.Quantity);cmd.Parameters.AddWithValue("$price",line.UnitPriceMinor);cmd.Parameters.AddWithValue("$lineTotal",line.UnitPriceMinor*line.Quantity);cmd.Parameters.AddWithValue("$name",line.Name);var saleLine=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));var remain=line.Quantity;
                while(remain>0){cmd.Parameters.Clear();cmd.CommandText="SELECT Id,QuantityOnHand,CostPriceMinor FROM Lots WHERE ProductId=$p AND QuantityOnHand>0 AND IsBlocked=0 AND (ExpiryDate IS NULL OR ExpiryDate>=date('now')) ORDER BY CASE WHEN ExpiryDate IS NULL THEN 1 ELSE 0 END,ExpiryDate,Id LIMIT 1";cmd.Parameters.AddWithValue("$p",line.ProductId);long lot;int available;long cost;await using(var r=await cmd.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))throw new InvalidOperationException($"Stock vendable insuffisant pour {line.Name}.");lot=r.GetInt64(0);available=r.GetInt32(1);cost=r.GetInt64(2);}var qty=Math.Min(remain,available);cmd.Parameters.Clear();cmd.CommandText="UPDATE Lots SET QuantityOnHand=QuantityOnHand-$q WHERE Id=$l AND QuantityOnHand>=$q;INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Reference) VALUES($p,$l,$u,'VENTE',-$q,$date,$sale);INSERT INTO SaleLotConsumptions(SaleLineId,LotId,Quantity,UnitCostMinor) VALUES($line,$l,$q,$cost);UPDATE SaleLines SET UnitCostMinor=CASE WHEN Quantity=0 THEN 0 ELSE $cost END WHERE Id=$line AND NOT EXISTS(SELECT 1 FROM SaleLotConsumptions WHERE SaleLineId=$line AND LotId<>$l)";cmd.Parameters.AddWithValue("$q",qty);cmd.Parameters.AddWithValue("$l",lot);cmd.Parameters.AddWithValue("$p",line.ProductId);cmd.Parameters.AddWithValue("$u",sale.UserId);cmd.Parameters.AddWithValue("$date",now.ToString("O"));cmd.Parameters.AddWithValue("$sale",number);cmd.Parameters.AddWithValue("$line",saleLine);cmd.Parameters.AddWithValue("$cost",cost);await cmd.ExecuteNonQueryAsync(ct);remain-=qty;}}
            foreach(var tender in sale.Tenders){cmd.Parameters.Clear();cmd.CommandText="INSERT INTO Payments(SaleId,Method,AmountMinor,PaidAt,ManualConfirmation) VALUES($s,$m,$a,$d,$c)";cmd.Parameters.AddWithValue("$s",saleId);cmd.Parameters.AddWithValue("$m",tender.Method);cmd.Parameters.AddWithValue("$a",tender.AmountMinor);cmd.Parameters.AddWithValue("$d",now.ToString("O"));cmd.Parameters.AddWithValue("$c",(object?)tender.Confirmation??DBNull.Value);await cmd.ExecuteNonQueryAsync(ct);}cmd.Parameters.Clear();cmd.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES($u,'VENTE_VALIDEE','Sales',$id,$d,$n)";cmd.Parameters.AddWithValue("$u",sale.UserId);cmd.Parameters.AddWithValue("$id",saleId);cmd.Parameters.AddWithValue("$d",now.ToString("O"));cmd.Parameters.AddWithValue("$n",number);await cmd.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);return saleId;
        }catch{await tx.RollbackAsync(ct);throw;}}
    public async Task<SaleReceipt> GetReceiptAsync(long saleId,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT s.ReceiptNumber,s.SoldAt,s.TotalMinor,s.DiscountMinor,u.Username,COALESCE((SELECT Value FROM PharmacySettings WHERE Key='Name'),'Pharmacie'),COALESCE((SELECT Value FROM PharmacySettings WHERE Key='Address'),''),COALESCE((SELECT Value FROM PharmacySettings WHERE Key='Phone'),'') FROM Sales s JOIN Users u ON u.Id=s.UserId WHERE s.Id=$id";cmd.Parameters.AddWithValue("$id",saleId);string number,date,seller,name,address,phone;long total,discount;await using(var r=await cmd.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))throw new KeyNotFoundException("Ticket introuvable.");number=r.GetString(0);date=r.GetString(1);total=r.GetInt64(2);discount=r.GetInt64(3);seller=r.GetString(4);name=r.GetString(5);address=r.GetString(6);phone=r.GetString(7);}cmd.Parameters.Clear();cmd.CommandText="SELECT ProductName,Quantity,UnitPriceMinor FROM SaleLines WHERE SaleId=$id";cmd.Parameters.AddWithValue("$id",saleId);var lines=new List<(string,int,long)>();await using(var r=await cmd.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))lines.Add((r.GetString(0),r.GetInt32(1),r.GetInt64(2)));cmd.Parameters.Clear();cmd.CommandText="SELECT Method,AmountMinor,ManualConfirmation FROM Payments WHERE SaleId=$id";cmd.Parameters.AddWithValue("$id",saleId);var payments=new List<Tender>();await using(var r=await cmd.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))payments.Add(new(r.GetString(0),r.GetInt64(1),r.IsDBNull(2)?null:r.GetString(2)));return new(saleId,number,DateTimeOffset.Parse(date),total,discount,seller,lines,payments,name,address,phone);}
    public async Task<long> ReverseSaleAsync(long saleId,long managerId,string type,string reason,long refundMinor,CancellationToken ct=default){if(!IsManager(await GetRole(managerId,ct)))throw new UnauthorizedAccessException("Cette opération est réservée au responsable.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Le motif est obligatoire.");if(type is not("RETOUR" or "ANNULATION"))throw new ArgumentException("Type d'opération inconnu.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="SELECT Status,TotalMinor FROM Sales WHERE Id=$s";cmd.Parameters.AddWithValue("$s",saleId);string status;long total;await using(var r=await cmd.ExecuteReaderAsync(ct)){if(!await r.ReadAsync(ct))throw new KeyNotFoundException("Vente introuvable.");status=r.GetString(0);total=r.GetInt64(1);}if(status!="VALIDEE")throw new InvalidOperationException("La vente n'est plus annulable ou retournable.");cmd.Parameters.Clear();cmd.CommandText="INSERT INTO SaleReversals(SaleId,UserId,Type,Reason,OccurredAt,RefundMinor) VALUES($s,$u,$t,$r,$d,$a);SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$s",saleId);cmd.Parameters.AddWithValue("$u",managerId);cmd.Parameters.AddWithValue("$t",type);cmd.Parameters.AddWithValue("$r",reason);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$a",refundMinor);var reversal=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));cmd.Parameters.Clear();cmd.CommandText="SELECT sl.Id,sl.ProductId,sl.Quantity-COALESCE((SELECT SUM(rl.Quantity) FROM SaleReturnLines rl WHERE rl.SaleLineId=sl.Id),0),COALESCE((SELECT c.LotId FROM SaleLotConsumptions c WHERE c.SaleLineId=sl.Id ORDER BY c.Id LIMIT 1),0) FROM SaleLines sl WHERE sl.SaleId=$s";cmd.Parameters.AddWithValue("$s",saleId);var items=new List<(long line,long product,int qty,long lot)>();await using(var r=await cmd.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))items.Add((r.GetInt64(0),r.GetInt64(1),r.GetInt32(2),r.GetInt64(3)));if(type=="ANNULATION"&&refundMinor>total)throw new ArgumentException("Le remboursement dépasse le montant de la vente.");foreach(var item in items.Where(x=>x.qty>0)){var q=type=="ANNULATION"?item.qty:item.qty;cmd.Parameters.Clear();cmd.CommandText="INSERT INTO Lots(ProductId,LotNumber,QuantityReceived,QuantityOnHand,CostPriceMinor,IsBlocked,BlockReason) VALUES($p,$lot,$q,$q,0,1,$reason);SELECT last_insert_rowid()";cmd.Parameters.AddWithValue("$p",item.product);cmd.Parameters.AddWithValue("$lot",$"RET-{reversal}-{item.line}");cmd.Parameters.AddWithValue("$q",q);cmd.Parameters.AddWithValue("$reason",reason);var blockedLot=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));cmd.Parameters.Clear();cmd.CommandText="INSERT INTO SaleReturnLines(ReversalId,SaleLineId,Quantity,LotId) VALUES($r,$line,$q,$lot);INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Reference,Notes) VALUES($p,$lot,$u,'RETOUR',$q,$d,$sale,$reason)";cmd.Parameters.AddWithValue("$r",reversal);cmd.Parameters.AddWithValue("$line",item.line);cmd.Parameters.AddWithValue("$q",q);cmd.Parameters.AddWithValue("$lot",blockedLot);cmd.Parameters.AddWithValue("$p",item.product);cmd.Parameters.AddWithValue("$u",managerId);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$sale",saleId.ToString());cmd.Parameters.AddWithValue("$reason",reason);await cmd.ExecuteNonQueryAsync(ct);}if(type=="ANNULATION"){cmd.Parameters.Clear();cmd.CommandText="UPDATE Sales SET Status='ANNULEE' WHERE Id=$s;INSERT INTO Payments(SaleId,Method,AmountMinor,PaidAt,ManualConfirmation) VALUES($s,'AUTRE',$refund,$d,$reason)";cmd.Parameters.AddWithValue("$s",saleId);cmd.Parameters.AddWithValue("$refund",refundMinor==0?total:refundMinor);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$reason","Remboursement annulation: "+reason);await cmd.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return reversal;}catch{await tx.RollbackAsync(ct);throw;}}
    public async Task AddCashMovementAsync(long sessionId,long userId,string type,long amount,string reason,CancellationToken ct=default){if(type is not("ENTREE" or "SORTIE")||amount<=0||string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Type, montant positif et motif obligatoire.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO CashMovements(SessionId,UserId,Type,AmountMinor,OccurredAt,Reason) SELECT $s,$u,$t,$a,$d,$r WHERE EXISTS(SELECT 1 FROM CashSessions WHERE Id=$s AND Status='OUVERTE')";cmd.Parameters.AddWithValue("$s",sessionId);cmd.Parameters.AddWithValue("$u",userId);cmd.Parameters.AddWithValue("$t",type);cmd.Parameters.AddWithValue("$a",amount);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$r",reason);if(await cmd.ExecuteNonQueryAsync(ct)!=1)throw new InvalidOperationException("Caisse fermée ou introuvable.");}
    public async Task CloseCashSessionAsync(long sessionId,long userId,long countedCash,CancellationToken ct=default){if(countedCash<0)throw new ArgumentOutOfRangeException(nameof(countedCash));await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="SELECT OpeningCashMinor FROM CashSessions WHERE Id=$s AND Status='OUVERTE'";cmd.Parameters.AddWithValue("$s",sessionId);var val=await cmd.ExecuteScalarAsync(ct);if(val is null)throw new InvalidOperationException("Session ouverte introuvable.");var opening=Convert.ToInt64(val);cmd.Parameters.Clear();cmd.CommandText="SELECT COALESCE(SUM(CASE WHEN p.Method='ESPECES' THEN p.AmountMinor ELSE 0 END),0),COALESCE(SUM(CASE WHEN p.Method<>'ESPECES' THEN p.AmountMinor ELSE 0 END),0) FROM Sales s JOIN Payments p ON p.SaleId=s.Id WHERE s.CashSessionId=$s AND s.Status='VALIDEE'";cmd.Parameters.AddWithValue("$s",sessionId);long cash,noncash;await using(var r=await cmd.ExecuteReaderAsync(ct)){await r.ReadAsync(ct);cash=r.GetInt64(0);noncash=r.GetInt64(1);}cmd.Parameters.Clear();cmd.CommandText="SELECT COALESCE(SUM(CASE WHEN Type='ENTREE' THEN AmountMinor ELSE -AmountMinor END),0) FROM CashMovements WHERE SessionId=$s";cmd.Parameters.AddWithValue("$s",sessionId);var movement=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));var expected=opening+cash+movement;if(expected<0)throw new InvalidOperationException("Les sorties de caisse dépassent les espèces disponibles.");cmd.Parameters.Clear();cmd.CommandText="INSERT INTO CashSessionClosures(SessionId,UserId,ClosedAt,CashSalesMinor,NonCashSalesMinor,ExpectedCashMinor,CountedCashMinor,DifferenceMinor) VALUES($s,$u,$d,$cash,$noncash,$expected,$count,$diff);UPDATE CashSessions SET Status='FERMEE',ClosedAt=$d,ClosingCashMinor=$count WHERE Id=$s AND Status='OUVERTE'";cmd.Parameters.AddWithValue("$s",sessionId);cmd.Parameters.AddWithValue("$u",userId);cmd.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));cmd.Parameters.AddWithValue("$cash",cash);cmd.Parameters.AddWithValue("$noncash",noncash);cmd.Parameters.AddWithValue("$expected",expected);cmd.Parameters.AddWithValue("$count",countedCash);cmd.Parameters.AddWithValue("$diff",countedCash-expected);await cmd.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}
    private async Task<string?> GetRole(long user,CancellationToken ct){await using var c=db.CreateConnection();await c.OpenAsync(ct);return await Role(c,null,user,ct);}
    private static async Task<string?> Role(SqliteConnection c,SqliteTransaction? tx,long user,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="SELECT r.Name FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE u.Id=$u AND u.IsActive=1";cmd.Parameters.AddWithValue("$u",user);return (string?)await cmd.ExecuteScalarAsync(ct);}
    private static bool IsManager(string? role)=>string.Equals(role,"Responsable",StringComparison.OrdinalIgnoreCase);
}
